/** The source of the runtime helper that switched code imports. It depends on the standard library only. */

export const SWITCH_HELPER_NAME = "__gate_mutant";
export const SWITCH_ALIAS = "__gateMutant";

const TEMPLATE = `// @ts-nocheck
// @generated by gate-typescript mutants --switch. Turns on at most one mutant per process and reports the ones reached.
import { appendFileSync } from "node:fs";

const IDS: string[] = "__MUTANT_IDS__";

const environment = (globalThis as any).process?.env ?? {};
const active: number = environment.GATE_MUTANT ? IDS.indexOf(environment.GATE_MUTANT) : -1;
const reachedFile: string = environment.GATE_MUTANT_REACHED ?? "";
const seen = new Uint8Array(IDS.length);
let kept: unknown;

function mark(index: number): void {
  seen[index] = 1;
  if (reachedFile) appendFileSync(reachedFile, IDS[index] + "\\n");
}

/** True when the mutant with this index is the active one. The first evaluation of each switch is recorded. */
function on(index: number): boolean {
  if (seen[index] === 0) mark(index);
  return index === active;
}

export const plus = (index: number, left: any, right: any): any => (on(index) ? left - right : left + right);
export const minus = (index: number, left: any, right: any): any => (on(index) ? left + right : left - right);
export const times = (index: number, left: any, right: any): any => (on(index) ? left / right : left * right);
export const divide = (index: number, left: any, right: any): any => (on(index) ? left * right : left / right);
export const eq = (index: number, left: any, right: any): boolean => (on(index) ? left != right : left == right);
export const ne = (index: number, left: any, right: any): boolean => (on(index) ? left == right : left != right);
export const same = (index: number, left: any, right: any): boolean => (on(index) ? left !== right : left === right);
export const differs = (index: number, left: any, right: any): boolean => (on(index) ? left === right : left !== right);
export const lt = (index: number, left: any, right: any): boolean => (on(index) ? left <= right : left < right);
export const le = (index: number, left: any, right: any): boolean => (on(index) ? left < right : left <= right);
export const gt = (index: number, left: any, right: any): boolean => (on(index) ? left >= right : left > right);
export const ge = (index: number, left: any, right: any): boolean => (on(index) ? left > right : left >= right);
export const bool = (index: number, value: boolean): boolean => (on(index) ? !value : value);
export const one = (value: any): any => value;
export const not = (index: number, value: any): any => (on(index) ? value : !value);

/** \`left && right\` is written \`and(i, left) ? right : last()\`: true means the right side decides the value. */
export function and(index: number, left: any): boolean {
  kept = left;
  return on(index) ? !left : !!left;
}

/** \`left || right\` is written \`or(i, left) ? right : last()\`. */
export function or(index: number, left: any): boolean {
  kept = left;
  return on(index) ? !!left : !left;
}

/** The left side that the and/or just before it decided to keep. Nothing runs between the two. */
export function last(): any {
  return kept;
}
`;

/** The helper with the ids of the switched mutants compiled in; a switch refers to a mutant by its index. */
export function switchHelperSource(ids: readonly string[]): string {
  return TEMPLATE.replace('"__MUTANT_IDS__"', () => JSON.stringify(ids));
}
